    internal static double3 Aab_to_JMh(double3 Aab,
        in JMhParams p)
    {
        double3 JMh = new double3(0.0, 0.0, 0.0);
        if (Aab[0] <= 0.0)
        {
            return JMh;
        }
        double J = Achromatic_n_to_J(Aab[0], p.cz);
        double M = sqrt(Aab[1] * Aab[1] + Aab[2] * Aab[2]);
        double h_rad = atan2(Aab[2], Aab[1]);
        double h = wrap_to_360(radians_to_degrees(h_rad));

        JMh[0] = J;
        JMh[1] = M;
        JMh[2] = h;

        return JMh;
    }

