    internal static double reinhard_remap(double scale,
        double nd,
        bool invert = false)
    {
        if (invert)
        {
            if (nd >= 1.0)
            {
                return scale;
            }
            else
            {
                return scale * -(nd / (nd - 1.0));
            }
        }
        return scale * nd / (1.0 + nd);
    }

    internal static double midpoint(double low, double high)
